            # Store the pressure value associated with this data line count
            press_values[data_line_count] = $4;
        }
    }

    # Stop processing data when we hit a clear non-data section marker
    data_start_flag == 1 && ($0 ~ /Performance:|MPI task timing breakdown:|Total wall time:/) {
        data_start_flag = 0;
        next;
    }

    END {
        # Total number of data points recorded
        total_data_points = data_line_count;

        # We want the second half, starting from step 2000.
        # If data_line_count is 4001 (steps 0-4000), the second half starts at index 2001.
        start_index = 2001;

        if (total_data_points < start_index) {
            print "ERROR: Not enough data points recorded to find the second half. Only " total_data_points " steps found (expected >= 2001).";
            exit;
        }

        sum_press = 0;
        count = 0;

        # Iterate from the starting index to the last recorded point
        for (i = start_index; i <= total_data_points; i++) {
            sum_press += press_values[i];
            count++;
        }

        mean = sum_press / count;
        printf "%.8f", mean;
    }
' $WORK/agents/rank-14/run/log.lammps

